/** Separate local encrypted photo/video vault. Never adds media to MediaStore. */
public class VaultActivity extends Activity {
 private static final int PICK=741; private static final String KEY_ALIAS="MDT_VAULT_AES_V1";
 private final Handler ui=new Handler(Looper.getMainLooper());
 private LinearLayout content; private SharedPreferences prefs; private int gridColumns=3; private boolean unlocked=false,albumUnlocked=false,busy=false,selecting=false;
 private final ArrayList<File> tempFiles=new ArrayList<>();
 private final ArrayList<JSONObject> entries=new ArrayList<>();
 private File vaultDir(){File d=new File(getFilesDir(),"vault");if(!d.exists())d.mkdirs();return d;}
 private File indexFile(){return new File(vaultDir(),"index.enc");}
 private SecretKey secret() throws Exception {java.security.KeyStore store=java.security.KeyStore.getInstance("AndroidKeyStore");store.load(null);
  if(!store.containsAlias(KEY_ALIAS)){KeyGenerator g=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(KEY_ALIAS,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).setKeySize(256).build());g.generateKey();}
  return ((java.security.KeyStore.SecretKeyEntry)store.getEntry(KEY_ALIAS,null)).getSecretKey();}
 private void encrypt(InputStream plain,OutputStream encrypted) throws Exception {Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,secret());byte[] iv=cipher.getIV();encrypted.write(iv.length);encrypted.write(iv);try(CipherOutputStream c=new CipherOutputStream(encrypted,cipher)){byte[] b=new byte[65536];int n;while((n=plain.read(b))!=-1)c.write(b,0,n);}}
 private void decrypt(InputStream encrypted,OutputStream plain) throws Exception {int n=encrypted.read();if(n!=12)throw new IOException("IV không hợp lệ");byte[] iv=new byte[n];new DataInputStream(encrypted).readFully(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,secret(),new GCMParameterSpec(128,iv));try(CipherInputStream in=new CipherInputStream(encrypted,c)){byte[] b=new byte[65536];int size;while((size=in.read(b))!=-1)plain.write(b,0,size);}}
 private void load() throws Exception {entries.clear();if(!indexFile().exists())return;ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=new FileInputStream(indexFile())){decrypt(in,out);}JSONArray json=new JSONArray(out.toString("UTF-8"));for(int i=0;i<json.length();i++)entries.add(json.getJSONObject(i));}
 private void save() throws Exception {JSONArray data=new JSONArray();for(JSONObject e:entries)data.put(e);File temp=new File(vaultDir(),"index.tmp");try(InputStream in=new ByteArrayInputStream(data.toString().getBytes("UTF-8"));OutputStream out=new FileOutputStream(temp)){encrypt(in,out);}if(indexFile().exists()&&!indexFile().delete())throw new IOException("Không ghi được mục lục");if(!temp.renameTo(indexFile()))throw new IOException("Không lưu được mục lục");}
 @Override public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("vault_security",MODE_PRIVATE);gridColumns=Math.max(1,Math.min(3,prefs.getInt("grid_columns",3)));// Screenshot blocking temporarily disabled for UI testing.
  getWindow().clearFlags(WindowManager.LayoutParams.FLAG_SECURE);unlocked=true;showPrivateHome();}
 private String digest(String text){try{MessageDigest md=MessageDigest.getInstance("SHA-256");byte[] bytes=md.digest(text.getBytes("UTF-8"));StringBuilder sb=new StringBuilder();for(byte x:bytes)sb.append(String.format(Locale.US,"%02x",x&255));return sb.toString();}catch(Exception e){return "";}}
 private TextView button(String name,Runnable task){TextView b=new TextView(this);b.setText(name);b.setTextColor(getSharedPreferences("settings",MODE_PRIVATE).getInt("color_button_text",-1));b.setTextSize(16);b.setGravity(Gravity.CENTER);b.setPadding(dp(14),dp(14),dp(14),dp(14));android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();SharedPreferences theme=getSharedPreferences("settings",MODE_PRIVATE);
  bg.setColor(theme.getInt("color_button",0xFFB47AFF));bg.setCornerRadius(dp(14));b.setBackground(bg);b.setOnClickListener(v->task.run());return b;}
 private void add(String s, int size){TextView t=new TextView(this);t.setText(s);t.setTextColor(0xFF202336);t.setTextSize(size);t.setPadding(8,14,8,14);content.addView(t);}
 private int dp(int value){return (int)(value*getResources().getDisplayMetrics().density+0.5f);}
 private void page(String heading){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);content=new LinearLayout(this);content.setOrientation(1);content.setPadding(dp(18),dp(14),dp(18),dp(26));content.setBackgroundColor(0xFFF4F2FA);scroll.addView(content);scroll.setFitsSystemWindows(true);getWindow().setStatusBarColor(0xFFF4F2FA);getWindow().setNavigationBarColor(0xFFF4F2FA);int flags=getWindow().getDecorView().getSystemUiVisibility();flags|=View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR;getWindow().getDecorView().setSystemUiVisibility(flags);setContentView(scroll);add(heading,25);}
 private void showGate(){if(!unlocked)return;String expected=prefs.getString("pin_hash","");if(expected.isEmpty()||albumUnlocked){openVault();return;}if(prefs.getBoolean("biometric",false)&&Build.VERSION.SDK_INT>=28){new AlertDialog.Builder(this).setTitle("Mở khóa Album ẩn").setItems(new String[]{"Nhập PIN","Dùng vân tay / sinh trắc học"},(d,w)->{if(w==1)biometricUnlock();else verifyPin(expected);}).show();}else verifyPin(expected);}
 interface PinAction{void done(String pin);}
 private void pinPrompt(String title,PinAction action){
  LinearLayout panel=new LinearLayout(this);panel.setOrientation(1);panel.setPadding(dp(18),dp(20),dp(18),dp(18));android.graphics.drawable.GradientDrawable panelBg=new android.graphics.drawable.GradientDrawable();panelBg.setColor(0xFFFFFFFF);panelBg.setCornerRadius(dp(20));panel.setBackground(panelBg);
  TextView label=new TextView(this);label.setText(title);label.setTextSize(22);label.setTextColor(0xFF173A52);label.setTypeface(null,1);label.setGravity(Gravity.CENTER);panel.addView(label);
  TextView hint=new TextView(this);hint.setText("Nhập mã PIN bảo vệ Album ẩn");hint.setGravity(Gravity.CENTER);hint.setTextColor(0xFF72818F);hint.setPadding(0,dp(7),0,dp(18));panel.addView(hint);
  LinearLayout digits=new LinearLayout(this);digits.setOrientation(0);digits.setGravity(Gravity.CENTER_VERTICAL);final TextView[] cells=new TextView[4];final boolean[] revealed={false};for(int i=0;i<4;i++){TextView cell=new TextView(this);cell.setTextSize(23);cell.setGravity(Gravity.CENTER);cell.setTextColor(0xFF124967);android.graphics.drawable.GradientDrawable cb=new android.graphics.drawable.GradientDrawable();cb.setColor(0xFFF1F6FA);cb.setCornerRadius(dp(10));cell.setBackground(cb);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(0,dp(57),1);lp.rightMargin=dp(6);digits.addView(cell,lp);cells[i]=cell;}
  TextView eye=new TextView(this);eye.setText("◉");eye.setTextSize(22);eye.setTextColor(0xFF135778);eye.setGravity(Gravity.CENTER);digits.addView(eye,new LinearLayout.LayoutParams(dp(36),dp(57)));panel.addView(digits);
  EditText input=new EditText(this);input.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(8)});input.setSingleLine(true);input.setTextColor(0x00000000);input.setBackgroundColor(0x00000000);input.setAlpha(.01f);panel.addView(input,new LinearLayout.LayoutParams(1,1));
  Runnable refresh=()->{String v=input.getText().toString();for(int i=0;i<4;i++){cells[i].setText(i<v.length()?(revealed[0]?String.valueOf(v.charAt(i)):"●"):"");}if(v.length()>4)hint.setText("Đã nhập "+v.length()+" chữ số");else hint.setText("Nhập mã PIN bảo vệ Album ẩn");};
  input.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int count,int after){}public void onTextChanged(CharSequence s,int st,int before,int count){refresh.run();}public void afterTextChanged(android.text.Editable e){}});eye.setOnClickListener(v->{revealed[0]=!revealed[0];refresh.run();});digits.setOnClickListener(v->input.requestFocus());
  TextView next=button("Tiếp tục",()->{});LinearLayout.LayoutParams nextLp=new LinearLayout.LayoutParams(-1,dp(52));nextLp.topMargin=dp(20);panel.addView(next,nextLp);
  AlertDialog dialog=new AlertDialog.Builder(this).setView(panel).create();next.setOnClickListener(v->{String pin=input.getText().toString();if(!pin.matches("[0-9]{4,8}")){Toast.makeText(this,"PIN cần 4–8 chữ số",Toast.LENGTH_SHORT).show();return;}dialog.dismiss();action.done(pin);});dialog.setOnShowListener(d->{if(dialog.getWindow()!=null)dialog.getWindow().setBackgroundDrawableResource(android.R.color.transparent);input.requestFocus();input.postDelayed(()->{android.view.inputmethod.InputMethodManager keyboard=(android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE);keyboard.showSoftInput(input,android.view.inputmethod.InputMethodManager.SHOW_IMPLICIT);},160);});dialog.show();
 }
 private void verifyPin(String expected){pinPrompt("Mở khóa Album ẩn",value->{if(expected.equals(digest(value))){albumUnlocked=true;openVault();}else{Toast.makeText(this,"Mã PIN không đúng",Toast.LENGTH_SHORT).show();showPrivateHome();}});}
 private void biometricUnlock(){if(Build.VERSION.SDK_INT<28){showGate();return;}try{android.hardware.biometrics.BiometricPrompt prompt=new android.hardware.biometrics.BiometricPrompt.Builder(this).setTitle("MDT Music — Album ẩn").setSubtitle("Xác thực để mở kho mã hóa").setNegativeButton("Nhập PIN",getMainExecutor(),(dialog,which)->verifyPin(prefs.getString("pin_hash",""))).build();prompt.authenticate(new android.os.CancellationSignal(),getMainExecutor(),new android.hardware.biometrics.BiometricPrompt.AuthenticationCallback(){@Override public void onAuthenticationSucceeded(android.hardware.biometrics.BiometricPrompt.AuthenticationResult result){albumUnlocked=true;openVault();}@Override public void onAuthenticationError(int code,CharSequence message){if(!isFinishing())verifyPin(prefs.getString("pin_hash",""));}});}catch(Exception e){verifyPin(prefs.getString("pin_hash",""));}}
 private void openVault(){try{load();albumUnlocked=true;showHome();}catch(Exception e){new AlertDialog.Builder(this).setTitle("Không thể mở kho mã hóa").setMessage("Không đọc được dữ liệu hoặc khóa thiết bị đã thay đổi. Không xóa hay gỡ ứng dụng để tránh mất dữ liệu.\n"+e.getMessage()).setPositiveButton("Đóng",(d,w)->finish()).show();}}
 private void showPrivateHome(){if(!unlocked)return;page("Khu vực riêng tư");
  add("Chọn chức năng",15);action(content,"▧ Album ẩn",this::showGate);
  action(content,"Ứng dụng ẩn trên Xiaomi",this::appHelp);
  action(content,"♫ Chuyển sang MDT Music",()->{albumUnlocked=false;unlocked=false;startActivity(new Intent(this,MainActivity.class));finish();});
 }
 private void action(LinearLayout parent, String label, Runnable handler){
  TextView v=button(label,handler);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(12);parent.addView(v,lp);
 }
 private void showHome(){if(!unlocked)return;if(!albumUnlocked){showGate();return;}page("Album ẩn");
  add(entries.size()+" ảnh/video đã lưu và mã hóa",14);
  action(content,"＋ Thêm ảnh / video",()->{if(busy)return;selecting=true;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"image/*","video/*"});i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,PICK);});
  action(content,"⚙ Cài đặt Album ẩn",this::settings);
  action(content,"‹ Quay lại khu vực riêng tư",()->{albumUnlocked=false;showPrivateHome();});
  LinearLayout toolbar=new LinearLayout(this);toolbar.setGravity(Gravity.CENTER_VERTICAL);toolbar.setOrientation(0);
  TextView title=new TextView(this);title.setText("Ảnh và video");title.setTextSize(16);title.setTextColor(0xFF202336);title.setTypeface(null,1);toolbar.addView(title,new LinearLayout.LayoutParams(0,-2,1));
  Spinner columns=new Spinner(this);String[] choices={"1 cột","2 cột","3 cột"};ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,choices);columns.setAdapter(adapter);columns.setSelection(gridColumns-1);columns.setContentDescription("Số cột hiển thị");columns.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> a){}public void onItemSelected(android.widget.AdapterView<?> a,View v,int position,long id){int count=position+1;if(gridColumns!=count){gridColumns=count;prefs.edit().putInt("grid_columns",count).apply();showHome();}}});toolbar.addView(columns,new LinearLayout.LayoutParams(dp(115),-2));content.addView(toolbar);
  TextView sort=new TextView(this);sort.setText("Sắp xếp: cũ nhất trước (thêm trước hiển thị trước)");sort.setTextColor(0xFF697087);sort.setTextSize(12);sort.setPadding(0,dp(8),0,dp(14));content.addView(sort);
  if(entries.isEmpty()){add("Chưa có ảnh hoặc video. Nhấn Thêm ảnh / video để nhập.",14);return;}
  GridLayout grid=new GridLayout(this);grid.setColumnCount(gridColumns);content.addView(grid,new LinearLayout.LayoutParams(-1,-2));
  int available=getResources().getDisplayMetrics().widthPixels-dp(44);int gap=dp(8);int tileWidth=Math.max(dp(70),(available-gap*(gridColumns-1))/gridColumns);
  for(JSONObject j:new ArrayList<>(entries)){
   LinearLayout tile=new LinearLayout(this);tile.setOrientation(1);tile.setBackground(makeCard());tile.setPadding(dp(5),dp(5),dp(5),dp(7));
   ImageView thumb=new ImageView(this);thumb.setScaleType(ImageView.ScaleType.CENTER_CROP);thumb.setBackgroundColor(0xFFE6E5ED);thumb.setImageResource(android.R.drawable.ic_menu_gallery);
   tile.addView(thumb,new LinearLayout.LayoutParams(-1,gridColumns==1?dp(200):tileWidth-dp(10)));
   if(j.optString("mime").startsWith("image/"))loadThumbnail(j,thumb);
   else {TextView video=new TextView(this);video.setText("▶ Video");video.setGravity(Gravity.CENTER);video.setTextColor(0xFF4B5162);tile.addView(video);}
   TextView filename=new TextView(this);filename.setText(j.optString("name","Ảnh / video"));filename.setTextColor(0xFF202336);filename.setTextSize(12);filename.setMaxLines(2);filename.setEllipsize(android.text.TextUtils.TruncateAt.END);tile.addView(filename);
   LinearLayout actions=new LinearLayout(this);actions.setGravity(Gravity.END);TextView open=new TextView(this);open.setText("Xem");open.setTextColor(0xFF4B5162);open.setPadding(dp(8),dp(9),dp(8),dp(9));open.setOnClickListener(v->view(j));actions.addView(open);
   TextView remove=new TextView(this);remove.setText("Xóa");remove.setTextColor(0xFFB94D61);remove.setPadding(dp(8),dp(9),dp(8),dp(9));remove.setOnClickListener(v->new AlertDialog.Builder(this).setTitle("Xóa khỏi Album ẩn?").setMessage("Tệp đã xóa sẽ không thể khôi phục nếu chưa sao lưu.").setNegativeButton("Hủy",null).setPositiveButton("Xóa",(d,w)->{new File(vaultDir(),j.optString("id")+".vault").delete();entries.remove(j);try{save();}catch(Exception ex){error(ex);}showHome();}).show());actions.addView(remove);tile.addView(actions);
   tile.setOnClickListener(v->view(j));GridLayout.LayoutParams gp=new GridLayout.LayoutParams();gp.width=tileWidth;gp.height=-2;gp.setMargins(0,0,gap,dp(10));grid.addView(tile,gp);
  }
 }
 private android.graphics.drawable.GradientDrawable makeCard(){android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();bg.setColor(0xFFFFFFFF);bg.setCornerRadius(dp(12));return bg;}
 private void loadThumbnail(JSONObject row,ImageView image){String id=row.optString("id");new Thread(()->{try{
   ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=new FileInputStream(new File(vaultDir(),id+".vault"))){decrypt(in,out);}byte[] raw=out.toByteArray();
   BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(raw,0,raw.length,bounds);int sample=1;while(Math.max(bounds.outWidth/sample,bounds.outHeight/sample)>480)sample*=2;
   BitmapFactory.Options opts=new BitmapFactory.Options();opts.inSampleSize=sample;Bitmap bitmap=BitmapFactory.decodeByteArray(raw,0,raw.length,opts);Arrays.fill(raw,(byte)0);if(bitmap!=null)ui.post(()->{if(!isFinishing())image.setImageBitmap(bitmap);});
  }catch(Exception ignored){} }).start();}
 private void settings(){page("Bảo mật Album ẩn");action(content,"Đặt / đổi mật khẩu lớp thứ hai",()->pinPrompt("Tạo mã PIN mới",first->pinPrompt("Nhập lại PIN",second->{if(!first.equals(second)){Toast.makeText(this,"PIN không khớp",Toast.LENGTH_LONG).show();return;}prefs.edit().putString("pin_hash",digest(first)).apply();Toast.makeText(this,"Đã đặt PIN",Toast.LENGTH_SHORT).show();})));
 action(content,"Tắt mật khẩu lớp thứ hai",()->{if(!prefs.contains("pin_hash"))return;pinPrompt("Nhập PIN hiện tại",pin->{if(digest(pin).equals(prefs.getString("pin_hash",""))){prefs.edit().remove("pin_hash").apply();Toast.makeText(this,"Đã tắt PIN",Toast.LENGTH_SHORT).show();}else Toast.makeText(this,"PIN sai",Toast.LENGTH_SHORT).show();});});
 action(content,"Bật / tắt mở khóa sinh trắc học",()->{if(Build.VERSION.SDK_INT<28||!prefs.contains("pin_hash")){Toast.makeText(this,"Cần Android 9+ và PIN lớp hai",Toast.LENGTH_LONG).show();return;}boolean enabled=!prefs.getBoolean("biometric",false);prefs.edit().putBoolean("biometric",enabled).apply();Toast.makeText(this,enabled?"Đã bật sinh trắc học":"Đã tắt sinh trắc học",Toast.LENGTH_SHORT).show();});add("• Tự khóa khi rời Album ẩn\n• Cho phép chụp màn hình trong bản thử nghiệm\n• Ảnh/video mã hóa AES-256-GCM bằng Android Keystore\n• Không tự xóa tệp gốc",14);
 action(content,"Quay lại Album ẩn",this::showHome);}
 private void appHelp(){page("Ẩn ứng dụng trên Xiaomi");add("MDT Music không thể tự gỡ icon của ứng dụng khác khỏi Xiaomi Launcher. Hãy dùng Bảo mật → Ẩn ứng dụng trên Xiaomi. Không chọn Gỡ cài đặt vì sẽ xóa ứng dụng.",16);content.addView(button("Mở cài đặt Android",()->{try{startActivity(new Intent(android.provider.Settings.ACTION_SETTINGS));}catch(Exception e){error(e);}}));action(content,"Quay lại",this::showPrivateHome);}
 private void error(Exception e){new AlertDialog.Builder(this).setTitle("Lỗi").setMessage(e.getMessage()).setPositiveButton("Đóng",null).show();}
 private String display(Uri uri){try(Cursor c=getContentResolver().query(uri,new String[]{OpenableColumns.DISPLAY_NAME},null,null,null)){if(c!=null&&c.moveToFirst())return c.getString(0);}catch(Exception e){}return "Tệp riêng tư";}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==PICK)selecting=false;if(request!=PICK||result!=RESULT_OK||data==null||busy)return;ArrayList<Uri> uris=new ArrayList<>();if(data.getClipData()!=null){for(int i=0;i<data.getClipData().getItemCount();i++)uris.add(data.getClipData().getItemAt(i).getUri());}else if(data.getData()!=null)uris.add(data.getData());if(uris.isEmpty())return;busy=true;ProgressDialog progress=new ProgressDialog(this);progress.setMessage("Đang mã hóa và lưu... Không đóng ứng dụng");progress.setCancelable(false);progress.show();new Thread(()->{int ok=0;String fail="";for(Uri uri:uris){String id=UUID.randomUUID().toString();File temp=new File(vaultDir(),id+".partial");try{String mime=getContentResolver().getType(uri);if(mime==null||!(mime.startsWith("image/")||mime.startsWith("video/")))throw new IOException("Không hỗ trợ định dạng này");try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(temp)){if(in==null)throw new IOException("Không đọc được tệp");encrypt(in,out);}File target=new File(vaultDir(),id+".vault");if(!temp.renameTo(target))throw new IOException("Không lưu được tệp");JSONObject row=new JSONObject();row.put("id",id);row.put("name",display(uri));row.put("mime",mime);entries.add(row);save();ok++;}catch(Exception ex){temp.delete();fail=ex.getMessage();}}int success=ok;String details=fail;ui.post(()->{busy=false;progress.dismiss();showHome();new AlertDialog.Builder(this).setTitle("Đã nhập "+success+"/"+uris.size()+" tệp").setMessage("Bản gốc trên điện thoại chưa bị xóa. Chỉ xóa bản gốc sau khi kiểm tra được tệp trong Album ẩn."+(details.isEmpty()?"":"\nLỗi: "+details)).setPositiveButton("OK",null).show();});}).start();}
 private void view(JSONObject row){String id=row.optString("id");File encrypted=new File(vaultDir(),id+".vault");if(!encrypted.isFile()){Toast.makeText(this,"Không tìm thấy file mã hóa",Toast.LENGTH_SHORT).show();return;}
 if(row.optString("mime").startsWith("image/")){try{ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=new FileInputStream(encrypted)){decrypt(in,out);}byte[] bytes=out.toByteArray();Bitmap bitmap=BitmapFactory.decodeByteArray(bytes,0,bytes.length);Arrays.fill(bytes,(byte)0);if(bitmap==null)throw new IOException("Ảnh không hợp lệ");ImageView image=new ImageView(this);image.setImageBitmap(bitmap);image.setAdjustViewBounds(true);new AlertDialog.Builder(this).setView(image).setPositiveButton("Đóng",null).show();}catch(Exception e){error(e);}return;}
 busy=true;ProgressDialog wait=new ProgressDialog(this);wait.setMessage("Đang giải mã video...");wait.setCancelable(false);wait.show();new Thread(()->{File tmp=null;try{tmp=File.createTempFile("mdt_preview_",".mp4",getCacheDir());try(InputStream in=new FileInputStream(encrypted);OutputStream out=new FileOutputStream(tmp)){decrypt(in,out);}File ready=tmp;ui.post(()->{busy=false;wait.dismiss();tempFiles.add(ready);VideoView player=new VideoView(this);player.setVideoPath(ready.getAbsolutePath());MediaController controls=new MediaController(this);player.setMediaController(controls);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(row.optString("name")).setView(player).setPositiveButton("Đóng",null).create();dialog.setOnDismissListener(d->{player.stopPlayback();ready.delete();tempFiles.remove(ready);});dialog.show();player.start();});}catch(Exception ex){if(tmp!=null)tmp.delete();Exception reason=ex;ui.post(()->{busy=false;wait.dismiss();error(reason);});}}).start();}
 @Override protected void onStop(){super.onStop();if(unlocked&&!busy&&!selecting){albumUnlocked=false;unlocked=false;for(File f:tempFiles)f.delete();tempFiles.clear();finish();}}
}
